import React from "react"
import "./App.css";
import Navigation from "./defaultresort/navigationpage";
const LazyHome = React.lazy( () => import("./defaultresort/mainhome/home") )

function App() {
  return (
    <>
      <Navigation />
      <React.Suspense fallback={<div>Loading....</div>} ><lazyHome /></React.Suspense>
    </>
  );
}

export default App;
